{"intent":"verify legacy article URLs redirect to root in .htaccess and _redirects","expect":"2809 legacy mappings covered or list missing mappings","script":"python3 - <<'PY'
import json,re
from pathlib import Path
items=json.loads(Path('data/articles.json').read_text(encoding='utf-8'))
expected=[]
for a in items:
    legacy=(a.get('legacyHref') or '').strip().lstrip('/')
    href=(a.get('href') or '').strip().lstrip('/')
    if legacy and href:
        expected.append((legacy,href))
ht=Path('.htaccess').read_text(encoding='utf-8', errors='replace') if Path('.htaccess').exists() else ''
rd=Path('_redirects').read_text(encoding='utf-8', errors='replace') if Path('_redirects').exists() else ''
missing_ht=[]; missing_rd=[]; wrong_ht=[]; wrong_rd=[]
for legacy,href in expected:
    # support RewriteRule ^legacy$ /href [R=301,L] or redirect lines
    if legacy not in ht:
        missing_ht.append((legacy,href))
    else:
        # local check near occurrence contains target href within 300 chars
        i=ht.find(legacy)
        if href not in ht[max(0,i-80):i+400]: wrong_ht.append((legacy,href,ht[max(0,i-80):i+220].replace('\n',' ')))
    if '/' + legacy not in rd and legacy not in rd:
        missing_rd.append((legacy,href))
    else:
        i=rd.find(legacy)
        if href not in rd[max(0,i-80):i+300]: wrong_rd.append((legacy,href,rd[max(0,i-80):i+180].replace('\n',' ')))
print('expected legacy mappings',len(expected))
print('.htaccess missing legacy token',len(missing_ht),'wrong nearby target',len(wrong_ht))
print('_redirects missing legacy token',len(missing_rd),'wrong nearby target',len(wrong_rd))
for label, rows in [('missing_ht',missing_ht),('wrong_ht',wrong_ht),('missing_rd',missing_rd),('wrong_rd',wrong_rd)]:
    if rows:
        print('\n',label)
        for r in rows[:10]: print(r)
