        meta_old.append(href)
print('files checked',len(items),'missing',len(missing),'old canonical link',len(canon_old),'old meta href-like',len(meta_old))
for row in canon_old[:10]: print('canonical',row)
for row in meta_old[:10]: print('meta',row)
